class HardwareTamperEnclosureMonitor:
    def __init__(self):
        self.mesh_continuity_ok = True
        self.voltage_in_range = True
        self.die_temperature_celsius = 25.0
        self.optical_seal_intact = True
        self.tamper_ram_zeroized = False
        self.audit = []

    def verify_physical_environment(self, v_supply: float, temp_c: float, mesh_cut: bool, light_detected: bool) -> tuple:
        self.die_temperature_celsius = temp_c
        self.audit.append(f"TAMPER_CHECK: V={v_supply}V, Temp={temp_c}C, MeshBroken={mesh_cut}, Light={light_detected}")

        # Check 1: Active Mesh Enclosure
        if mesh_cut:
            self.mesh_continuity_ok = False
            return self._trigger_hardware_tamper("ACTIVE_MESH_SEVERED")

        # Check 2: Optical Sensor (Decapping)
        if light_detected:
            self.optical_seal_intact = False
            return self._trigger_hardware_tamper("SILICON_DECAPPING_LIGHT_DETECTED")

        # Check 3: Voltage Glitch Sensor (Normal: 3.0V - 3.6V)
        if v_supply < 2.7 or v_supply > 3.8:
            self.voltage_in_range = False
            return self._trigger_hardware_tamper(f"VOLTAGE_GLITCH_DETECTED_{v_supply}V")

        # Check 4: Thermal Glitch Sensor (-40C to 85C)
        if temp_c > 105.0 or temp_c < -45.0:
            return self._trigger_hardware_tamper(f"EXTREME_THERMAL_TAMPER_{temp_c}C")

        return True, "ENVIRONMENT_NORMAL"

    def _trigger_hardware_tamper(self, reason: str) -> tuple:
        # Hardware rail discharge clears tamper RAM in < 10ns
        self.tamper_ram_zeroized = True
        self.audit.append(f" -> CRITICAL_TAMPER_TRIP: {reason}! Zeroizing Tamper RAM instantly.")
        return False, f"TAMPER_ALARM_{reason}"

tamper_hw = HardwareTamperEnclosureMonitor()

# Condition 1: Nominal operation
ok1, stat1 = tamper_hw.verify_physical_environment(v_supply=3.3, temp_c=32.0, mesh_cut=False, light_detected=False)
print(f"Nominal State: {stat1} (Tamper Zeroized: {tamper_hw.tamper_ram_zeroized})")

# Condition 2: Attacker injects voltage fault glitch (2.2V dip)
ok2, stat2 = tamper_hw.verify_physical_environment(v_supply=2.2, temp_c=32.0, mesh_cut=False, light_detected=False)
print(f"Glitch State: {stat2} (Tamper Zeroized: {tamper_hw.tamper_ram_zeroized})")

print("Hardware Tamper Audit Trail:")
for log in tamper_hw.audit:
    print(f" {log}")

class EmbeddedCveAnalyzer:
    VULNERABILITY_PATTERNS = {
        "UNSAFE_STRING_COPY": {"cwe": "CWE-121", "severity": "CRITICAL", "desc": "Unbounded strcpy/sprintf causes stack overflow"},
        "INTEGER_OVERFLOW_ALLOC": {"cwe": "CWE-190", "severity": "HIGH", "desc": "Arithmetic overflow in buffer allocation sizing"},
        "UNPROTECTED_TOCTOU_DMA": {"cwe": "CWE-367", "severity": "HIGH", "desc": "Flash read window allows DMA modification post-verification"}
    }

    def __init__(self):
        self.findings = []
        self.audit = []

    def inspect_firmware_routine(self, routine_name: str, code_snippet: str) -> list:
        routine_findings = []

        if "strcpy(" in code_snippet or "sprintf(" in code_snippet:
            pat = self.VULNERABILITY_PATTERNS["UNSAFE_STRING_COPY"]
            routine_findings.append({"routine": routine_name, **pat, "mitigation": "Replace with snprintf() or bounded memcpy()"})

        if "malloc(count * size)" in code_snippet:
            pat = self.VULNERABILITY_PATTERNS["INTEGER_OVERFLOW_ALLOC"]
            routine_findings.append({"routine": routine_name, **pat, "mitigation": "Use __builtin_mul_overflow() or static pool"})

        if "verify_flash()" in code_snippet and "dma_active" in code_snippet:
            pat = self.VULNERABILITY_PATTERNS["UNPROTECTED_TOCTOU_DMA"]
            routine_findings.append({"routine": routine_name, **pat, "mitigation": "Disable DMA or copy into internal SRAM"})

        for f in routine_findings:
            self.findings.append(f)
            self.audit.append(f"CVE_ALERT: [{f['severity']}] {f['cwe']} in '{routine_name}': {f['desc']}")

        return routine_findings

analyzer = EmbeddedCveAnalyzer()

# Audit suspect legacy C routines
sample_routine_1 = "void parse_uri(char *u) { char buf[32]; strcpy(buf, u); }"
sample_routine_2 = "void *alloc_frame(int count, int size) { return malloc(count * size); }"

f1 = analyzer.inspect_firmware_routine("parse_uri", sample_routine_1)
f2 = analyzer.inspect_firmware_routine("alloc_frame", sample_routine_2)

print(f"Total CVE Flaws Detected: {len(analyzer.findings)}")
for item in analyzer.findings:
    print(f" - {item['cwe']} in {item['routine']} ({item['severity']}): {item['mitigation']}")

print("Analyzer Audit Trail:")
for log in analyzer.audit:
    print(f" {log}")
